package terminalsession

import (
	"errors"
	"regexp"
	"strings"
)

var installLogToken = regexp.MustCompile("^[a-f0-9]{32}$")

// All paths are generated by the panel, never supplied by a browser.
func InstallTmuxLoggedCommands(token string) (install, read, cleanup string, err error) {
	if !installLogToken.MatchString(token) {
		return "", "", "", errors.New("invalid install log token")
	}
	dir := "/tmp/nezha-tmux-install-" + token
	log := dir + "/output.log"
	original := "log=$(mktemp /tmp/nezha-tmux-install.XXXXXX) || { printf 'NZX_DISK\\n'; exit 0; }\ntrap 'rm -f -- \"$log\"' EXIT"
	replacement := "mkdir -m 700 -- " + Quote(dir) + " || { printf 'NZX_DISK\\n'; exit 0; }\nlog=" + Quote(log) + "\nprintf 'Preparing package manager...\\n' >\"$log\""
	install = strings.Replace(InstallTmuxCommand, original, replacement, 1)
	install = strings.Replace(install, " >\"$log\" 2>&1", " >>\"$log\" 2>&1", 1)
	read = "if [ ! -L " + Quote(dir) + " ] && [ ! -L " + Quote(log) + " ] && [ -f " + Quote(log) + " ]; then tail -c 32769 -- " + Quote(log) + "; fi"
	cleanup = "if [ ! -L " + Quote(dir) + " ] && [ -d " + Quote(dir) + " ]; then rm -f -- " + Quote(log) + " && rmdir -- " + Quote(dir) + "; fi"
	return
}
